body:
Hey, this is my first PR / contribution to the engine 👋

### Description:
This PR extends the `ResourceLoader` by 4 public methods for retrieval of either all or only filtered "cached" resource paths as arrays or dictionaries in C++, GDScript and C#

**Note(s)** 
A Resource is considered cached when **all of the following conditions are true**:
- It must have a `get_reference_count() > 0` (assigned to exported variables via inspector or assigned to any variable via code)
- It must have a valid `resource_path` set (Examples: `res://icon.svg` or `C:/path/to/my/file.png` )

**Usages:**
```js
extends Node
class_name GdScriptTestNode

@export var resources : Array[Resource]

func _ready() -> void:
	var all_entries_dict = ResourceLoader.get_cached_entries()
	print(JSON.stringify(all_entries_dict, "\t"))

	var all_paths_types = ResourceLoader.get_cached_paths_infos(ResourceLoader.FilterTarget.FILTER_TARGET_TYPE_HINT);
	print(JSON.stringify(all_paths_types, "\t"));

	var all_image_entries = ResourceLoader.get_cached_entries_filtered(
		ResourceLoader.FilterTarget.FILTER_TARGET_TYPE_HINT,
		ResourceLoader.FilterComparator.FILTER_COMP_EQUALS,
		"Image",

	);
	print(JSON.stringify(all_image_entries, "\t"))
	
	var all_res_paths_types = ResourceLoader.get_cached_paths_infos_filtered(
		ResourceLoader.FilterTarget.FILTER_TARGET_TYPE_HINT,
		ResourceLoader.FilterTarget.FILTER_TARGET_PATH,
		ResourceLoader.FILTER_COMP_BEGINS_WITH,
		"res://new"
	);
	print(JSON.stringify(all_res_paths_types, "\t"))
```

```cs
using Godot;
using Godot.Collections;

[GlobalClass]
public partial class TestNode : Node
{
    [Export] public Array<Resource> Resources;

    public override void _Ready()
    {
        var allEntriesDict = ResourceLoader.GetCachedEntries();
        GD.Print(Json.Stringify(allEntriesDict, "\t"));
        
        var allPathsTypesDict  = ResourceLoader.GetCachedPathsInfos(ResourceLoader.FilterTarget.TypeHint);
        GD.Print(Json.Stringify(allPathsTypesDict, "\t"));
        
        var allImgPaths  = ResourceLoader.GetCachedEntriesFiltered(
            ResourceLoader.FilterTarget.TypeHint, 
            ResourceLoader.FilterComparator.Equals, 
            "Image",
            100
        );
        GD.Print(Json.Stringify(allImgPaths, "\t"));
        
        var allResPaths  = ResourceLoader.GetCachedPathsInfosFiltered(
            ResourceLoader.FilterTarget.TypeHint, 
            ResourceLoader.FilterTarget.Path, 
            ResourceLoader.FilterComparator.BeginsWith, 
            "res://new",
            100
        );
        GD.Print(Json.Stringify(allResPaths, "\t"));
    }
}
```

